INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ng-aj20-attack-jet-pack', 'NG-AJ20 Attack Jet Pack', 'rifts', 'gear', 91, 280000, '280,000 credits combustion or electric, 590,000 Solid Oxide, 950,000 nuclear with a 10 year life (rare); the lowest is stored.', 'Shoulder lasers: 2D6 M.D. per single blast, 4D6 M.D. per simultaneous blast from both at one target', 1, '2,000 ft (610 m)', 'Effectively unlimited on nuclear or Solid Oxide; 60 shots each per charge on electric; combustion packs take one E-Clip per laser, 20 shots a clip', 'Each blast is one melee attack', NULL, NULL, 50, 'NG''s newest jet pack, a heavy unit halfway between an ordinary pack and flying power armor and far cheaper than the latter. Two built-in lasers ride over the shoulders, each turning left, right, up and down 25 degrees, though the wearer mostly aims with his whole body; with them one soldier can dogfight light power armor, rocket bikes and Sky Cycles, or hit towers, rooftops, ground troops and vehicles from above. Laser penalties: -1 to strike, no aimed or Called Shot unless hovering still, and -5% piloting in combat on top of the usual dogfighting penalties. Up to 90 mph (144 km), ceiling 1,200 ft (366 m). Range: combustion 250 miles (400 km), electric 600 miles (960 km), Solid Oxide and nuclear unlimited, but any version run more than five hours straight may overheat (01-40%) and burn out for good; give it an hour to cool every three or four hours. It can be wired to power armor''s own supply for unlimited flight, though 65% of users keep it a detachable, even throwaway, unit. Size 3.5 ft (1.1 m).', 'Rifts World Book 34: Northern Gun Two p.193', NULL),
  ('ng-wj10-speedpack', 'NG-WJ10 Speedpack', 'rifts', 'gear', 45, 38000, 'Black Market: 38,000 credits gasoline, 60,000 electric, 350,000 Solid Oxide, 875,000 nuclear with a 10 year life; the lowest is stored.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 30, 'A small personal jet pack, NG''s long-selling copy of the Wilk''s. It wears as a backpack harness or plugs into connectors on most NG body armor and power armor, and comes with a helmet, neck brace, a 3 mile (4.8 km) radio and a compass. One flyer, up to 120 mph (192 km), ceiling 1,400 ft (426 m). Range: combustion 400 miles (640 km), electric 800 miles (1,280 km), Solid Oxide and nuclear unlimited, but past four hours of nonstop use any version may overheat (01-40%) and burn out; rest it two hours after every two or three. It can draw on power armor''s supply for unlimited flight, though 96% of users keep it removable. Size 3 ft (0.9 m). No built-in weapons; ordinary handguns and rifles can be fired in flight.', 'Rifts World Book 34: Northern Gun Two p.193', NULL),
  ('ng-j45-wolf-runner-jet-pack', 'NG-J45 Wolf-Runner Jet Pack', 'rifts', 'gear', 78, 76000, '76,000 credits combustion, 125,000 electric, 390,000 Solid Oxide, 920,000 nuclear; the lowest is stored. Tying it into power armor''s supply is 385,000 to 485,000 more.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 50, 'A big, heavy personal jet pack for heavy power armor and anyone wanting dependable, sustained, fast flight. It mounts as a backpack on non-environmental armor, EBA and light power armor and is unsafe for an unarmored user; it answers voice or code commands through the armor''s or helmet''s comms, or codes typed on a mini wrist computer. One armored flyer, up to 90 mph (144 km), ceiling 1,200 ft (366 m). Range: combustion 250 miles (400 km), electric 500 miles (800 km), Solid Oxide and nuclear unlimited, but more than four hours of nonstop use risks overheating (01-40%) and burnout; rest it two hours after every two or three. It can run off power armor''s supply for unlimited flight, though 90% of users keep it detachable (the entry''s own text calls it the Wild Coyote there). Size 3.5 ft (1.1 m). No built-in weapons; ordinary handguns and rifles can be fired in flight.', 'Rifts World Book 34: Northern Gun Two p.194', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 gear rows are in' AS assertion, count(*) AS got, 3 AS want
  FROM gear WHERE slug IN ('ng-aj20-attack-jet-pack', 'ng-wj10-speedpack', 'ng-j45-wolf-runner-jet-pack') AND source_book IS NOT NULL;

